import Foundation
import Testing
@testable import MarblesCore

/// Cross-client check: `lastHourWindow` matches the web for every golden zone
/// (ios/Fixtures/golden/time.<zone>.json, generated by `npm run golden`).
struct GoldenLastHourTests {
    struct Fixture: Decodable {
        struct Case: Decodable {
            struct Input: Decodable {
                let now: String?
                let nowEpochMs: Double?
            }
            let fn: String
            let input: Input
            let output: [SlotRef]?

            enum CodingKeys: String, CodingKey { case fn, input, output }

            init(from decoder: Decoder) throws {
                let c = try decoder.container(keyedBy: CodingKeys.self)
                fn = try c.decode(String.self, forKey: .fn)
                input = (try? c.decode(Input.self, forKey: .input)) ?? Input(now: nil, nowEpochMs: nil)
                output = fn == "lastHourWindow" ? try c.decode([SlotRef].self, forKey: .output) : nil
            }
        }
        let cases: [Case]
    }

    static let goldenDir = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent()  // MarblesCoreTests
        .deletingLastPathComponent()  // Tests
        .deletingLastPathComponent()  // MarblesCore
        .deletingLastPathComponent()  // Packages
        .deletingLastPathComponent()  // ios
        .appendingPathComponent("Fixtures/golden")

    @Test(arguments: ["America/Los_Angeles", "Australia/Lord_Howe", "Asia/Kolkata", "UTC"])
    func lastHourMatchesWeb(zone: String) throws {
        let url = Self.goldenDir.appendingPathComponent("time.\(zone.replacingOccurrences(of: "/", with: "_")).json")
        let fixture = try JSONDecoder().decode(Fixture.self, from: Data(contentsOf: url))
        let ctx = TimeContext.fixed(zone)
        let cases = fixture.cases.filter { $0.fn == "lastHourWindow" }
        #expect(cases.count >= 14)
        for c in cases {
            let ms = try #require(c.input.nowEpochMs)
            let now = Date(timeIntervalSince1970: ms / 1000)
            #expect(lastHourWindow(now: now, in: ctx) == c.output, "\(zone) \(c.input.now ?? "")")
        }
    }
}
